//! The vocabulary of the W3C Data Integrity v2 `@context`: the IRIs it
//! expands the members of a proof to, and the datatypes it coerces their
//! values to.
//!
//! ETSI GS CIM 009 v1.9.1 clause 4.5.2.2 has the `value` of an `ngsildproof`
//! hold the W3C Data Integrity proof structure, and the core `@context` scopes
//! the Data Integrity v2 context to the `ngsildproof` term. That context is
//! `@protected`, so a proof expands to these IRIs under any user `@context`.
//!
//! The term constants are generated by [`jsonld::vocab!`] from the document
//! [`crate::data_integrity_context`] embeds, its scoped term definitions
//! included. Two coercion targets are no term of that document but the bare
//! `@type` of one, so they are written out here, as the crate root writes out
//! the bare datatypes of the core context.

use iri_rs::{Iri, iri};

jsonld::vocab! {
    contexts: ["context/data-integrity-v2.jsonld"]
}

/// The datatype the context coerces `cryptosuite` to.
pub const CRYPTOSUITE_STRING: Iri<&'static str> = iri!("https://w3id.org/security#cryptosuiteString");

/// The datatype the context coerces `proofValue` to.
pub const MULTIBASE: Iri<&'static str> = iri!("https://w3id.org/security#multibase");

#[cfg(test)]
mod tests {
    use crate::{
        data_integrity_context::DATA_INTEGRITY_CONTEXT,
        data_integrity_vocabulary::{
            CRYPTOSUITE_STRING,
            MULTIBASE,
            expanded::{classes, properties},
        },
    };
    use serde_json::{Value, json};

    /// The term definitions the context gives inside `DataIntegrityProof`.
    fn proof_terms() -> Value {
        let document: Value = serde_json::from_str(DATA_INTEGRITY_CONTEXT).expect("the document is JSON");
        document["@context"]["DataIntegrityProof"]["@context"].clone()
    }

    #[test]
    fn the_scoped_proof_terms_are_generated() {
        pretty_assertions::assert_eq!(classes::DATA_INTEGRITY_PROOF.as_str(), "https://w3id.org/security#DataIntegrityProof");
        pretty_assertions::assert_eq!(properties::CREATED.as_str(), "http://purl.org/dc/terms/created");
        pretty_assertions::assert_eq!(properties::PROOF_VALUE.as_str(), "https://w3id.org/security#proofValue");
        pretty_assertions::assert_eq!(properties::ASSERTION_METHOD.as_str(), "https://w3id.org/security#assertionMethod");
    }

    #[test]
    fn the_coercion_targets_are_the_datatypes_the_context_names() {
        let terms = proof_terms();
        pretty_assertions::assert_eq!(terms["cryptosuite"]["@type"], json!(CRYPTOSUITE_STRING.as_str()));
        pretty_assertions::assert_eq!(terms["proofValue"]["@type"], json!(MULTIBASE.as_str()));
    }
}
